DROP DATABASE IF EXISTS hrm_enterprise_db;
CREATE DATABASE hrm_enterprise_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE hrm_enterprise_db;

CREATE TABLE departments(department_id INT AUTO_INCREMENT PRIMARY KEY,department_name VARCHAR(150) NOT NULL,created_at DATE NOT NULL);
CREATE TABLE jobs(job_id INT AUTO_INCREMENT PRIMARY KEY,department_id INT NOT NULL,job_title VARCHAR(150) NOT NULL,base_salary_min DECIMAL(15,2) NOT NULL,base_salary_max DECIMAL(15,2) NOT NULL,target_headcount INT NOT NULL,FOREIGN KEY(department_id) REFERENCES departments(department_id));
CREATE TABLE projects(project_id INT AUTO_INCREMENT PRIMARY KEY,project_name VARCHAR(180) NOT NULL,required_headcount INT NOT NULL,start_date DATE,status VARCHAR(30) NOT NULL);
CREATE TABLE employees(employee_id INT PRIMARY KEY,job_id INT NOT NULL,department_id INT NOT NULL,full_name VARCHAR(180) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,base_salary DECIMAL(15,2) NOT NULL,hire_date DATE NOT NULL,resignation_date DATE,status ENUM('ACTIVE','RESIGNED') NOT NULL,dependent_count INT NOT NULL DEFAULT 0,FOREIGN KEY(job_id) REFERENCES jobs(job_id),FOREIGN KEY(department_id) REFERENCES departments(department_id),INDEX idx_hire_year(hire_date),INDEX idx_status(status));
CREATE TABLE employment_events(event_id BIGINT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,event_type ENUM('JOIN','REWARD','DISCIPLINE','LEAVE','PROMOTION','SALARY_RAISE','OVERTIME','RESIGN') NOT NULL,event_date DATE NOT NULL,description VARCHAR(500),FOREIGN KEY(employee_id) REFERENCES employees(employee_id),INDEX idx_event_year(event_date));
CREATE TABLE rewards_disciplines(record_id BIGINT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,type ENUM('REWARD','DISCIPLINE') NOT NULL,amount DECIMAL(15,2) DEFAULT 0,reason VARCHAR(300),record_date DATE NOT NULL,FOREIGN KEY(employee_id) REFERENCES employees(employee_id));
CREATE TABLE attendance_records(attendance_id BIGINT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,work_date DATE NOT NULL,work_days DECIMAL(5,2) NOT NULL DEFAULT 1,check_in TIME,check_out TIME,status ENUM('PRESENT','LEAVE','ABSENT') NOT NULL DEFAULT 'PRESENT',FOREIGN KEY(employee_id) REFERENCES employees(employee_id),UNIQUE KEY uk_attendance(employee_id,work_date));
CREATE TABLE leave_records(leave_id BIGINT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,leave_type VARCHAR(50) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,total_days DECIMAL(5,2) NOT NULL,reason VARCHAR(300),FOREIGN KEY(employee_id) REFERENCES employees(employee_id));
CREATE TABLE overtime_records(ot_id BIGINT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,work_date DATE NOT NULL,hours DECIMAL(6,2) NOT NULL,hourly_rate DECIMAL(15,2) NOT NULL,multiplier DECIMAL(4,2) DEFAULT 1.5,FOREIGN KEY(employee_id) REFERENCES employees(employee_id),INDEX idx_ot_date(work_date),UNIQUE KEY uk_ot_employee_date(employee_id,work_date));
CREATE TABLE payrolls(payroll_id BIGINT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,pay_month INT NOT NULL,pay_year INT NOT NULL,base_salary DECIMAL(15,2) NOT NULL,overtime_pay DECIMAL(15,2) NOT NULL,bonus DECIMAL(15,2) NOT NULL,deduction DECIMAL(15,2) NOT NULL,net_salary DECIMAL(15,2) NOT NULL,status ENUM('DRAFT','SENT') NOT NULL DEFAULT 'DRAFT',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,sent_at TIMESTAMP NULL,UNIQUE KEY uk_emp_month(employee_id,pay_month,pay_year),FOREIGN KEY(employee_id) REFERENCES employees(employee_id));
CREATE TABLE project_allocations(allocation_id BIGINT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,employee_id INT NOT NULL,role_in_project VARCHAR(120),assigned_date DATE,UNIQUE KEY uk_project_employee(project_id,employee_id),FOREIGN KEY(project_id) REFERENCES projects(project_id),FOREIGN KEY(employee_id) REFERENCES employees(employee_id));
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,employee_id INT UNIQUE NULL,username VARCHAR(80) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('ADMIN','HR','ACCOUNTANT','EMPLOYEE') NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(employee_id) REFERENCES employees(employee_id));
CREATE TABLE system_logs(log_id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) NOT NULL,action_type VARCHAR(100) NOT NULL,details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);


DELIMITER $$
CREATE PROCEDURE seed_data()
BEGIN
 DECLARE i INT DEFAULT 1; DECLARE yr INT; DECLARE d INT; DECLARE j INT; DECLARE hd DATE; DECLARE rd DATE; DECLARE st VARCHAR(10); DECLARE fn VARCHAR(180); DECLARE email VARCHAR(180); DECLARE sal DECIMAL(15,2); DECLARE typ INT;
 WHILE i<=2500 DO
   SET yr=2022+FLOOR((i-1)/500); SET d=1+MOD(i-1,8); SET j=1+MOD(i-1,40); SET typ=MOD(i-1,24)+1;
   SET hd=DATE_ADD(STR_TO_DATE(CONCAT(yr,'-01-01'),'%Y-%m-%d'),INTERVAL MOD(i*37,330) DAY);
   SET st=IF(yr<2026 AND MOD(i,7)=0,'RESIGNED','ACTIVE'); SET rd=IF(st='RESIGNED',DATE_ADD(hd,INTERVAL (180+MOD(i*13,500)) DAY),NULL);
   SET fn=CONCAT(
     ELT(1+MOD(i,18),'Nguyễn','Trần','Lê','Phạm','Hoàng','Vũ','Đặng','Bùi','Đỗ','Hồ','Ngô','Dương','Đinh','Võ','Mai','Phan','Tạ','Cao'),' ',
     ELT(1+MOD(i*3,18),'Văn','Thị','Minh','Ngọc','Gia','Đức','Thanh','Hoàng','Quang','Hữu','Thùy','Kim','Tuấn','Anh','Khánh','Phương','Nhật','Bảo'),' ',
     ELT(1+MOD(i*7,30),'An','Anh','Bình','Châu','Dũng','Hải','Hạnh','Hiếu','Hùng','Hương','Khang','Khoa','Khôi','Lan','Linh','Long','Mai','Minh','Nam','Nga','Ngân','Phúc','Quân','Sơn','Trang','Trung','Tuấn','Uyên','Vy','Yến'));
   SET email=CONCAT('NV',LPAD(i,4,'0'),'@gmail.com');
   SELECT base_salary_min + RAND()*(base_salary_max-base_salary_min) INTO sal FROM jobs WHERE job_id=j;
   IF MOD(i,5)=0 THEN INSERT INTO employment_events(employee_id,event_type,event_date,description) VALUES(i,'REWARD',DATE_ADD(hd,INTERVAL 250 DAY),'Được thưởng do hoàn thành tốt công việc'); INSERT INTO rewards_disciplines(employee_id,type,amount,reason,record_date) VALUES(i,'REWARD',1000000+MOD(i,8)*500000,'Hoàn thành KPI',DATE_ADD(hd,INTERVAL 250 DAY)); END IF;
   IF MOD(i,6)=0 THEN INSERT INTO employment_events(employee_id,event_type,event_date,description) VALUES(i,'PROMOTION',DATE_ADD(hd,INTERVAL 360 DAY),'Được thăng cấp theo đánh giá hiệu suất'); END IF;
   IF MOD(i,4)=0 THEN INSERT INTO employment_events(employee_id,event_type,event_date,description) VALUES(i,'SALARY_RAISE',DATE_ADD(hd,INTERVAL 420 DAY),'Tăng lương định kỳ'); END IF;
   IF MOD(i,3)=0 THEN INSERT INTO overtime_records(employee_id,work_date,hours,hourly_rate,multiplier) VALUES(i,DATE_ADD(hd,INTERVAL 30 DAY),8+MOD(i,13),sal/26/8,1.5); INSERT INTO employment_events(employee_id,event_type,event_date,description) VALUES(i, 'OVERTIME',DATE_ADD(hd,INTERVAL 30 DAY),'Có phát sinh làm thêm giờ'); END IF;
   IF MOD(i,9)=0 THEN INSERT INTO employment_events(employee_id,event_type,event_date,description) VALUES(i,'LEAVE',DATE_ADD(hd,INTERVAL 180 DAY),'Nghỉ phép trong năm'); END IF;
   IF st='RESIGNED' THEN INSERT INTO employment_events(employee_id,event_type,event_date,description) VALUES(i,'RESIGN',rd,'Nhân viên rời công ty'); END IF;
   SET i=i+1;
 END WHILE;
END$$
DELIMITER ;
CALL seed_data();
DROP PROCEDURE seed_data;

-- Chấm công mẫu: một bản ghi đại diện mỗi nhân viên trong mỗi năm tuyển dụng.
SELECT e.employee_id,DATE_ADD(e.hire_date,INTERVAL 20 DAY),1,'08:00:00','17:30:00','PRESENT' FROM employees e;
SELECT employee_id,'Nghỉ phép',DATE_ADD(hire_date,INTERVAL 180 DAY),DATE_ADD(hire_date,INTERVAL 181 DAY),2,'Nghỉ phép năm' FROM employees WHERE MOD(employee_id,9)=0;
SELECT employee_id,'LEAVE',start_date,'Nghỉ phép' FROM leave_records;

-- Phân bổ nhân viên hiện tại vào dự án, không vượt số lượng cần.
-- Phân bổ mẫu theo nhiều mức độ thiếu nhân sự: tất cả dự án đều có thành viên nhưng chưa dự án nào đủ định biên.
-- Mỗi nhân viên mẫu được đưa vào tối đa một dự án ở dữ liệu ban đầu; có thể phân công thêm qua giao diện.
SELECT CASE
 WHEN MOD(e.employee_id,100) BETWEEN 0 AND 4 THEN 1
 WHEN MOD(e.employee_id,100) BETWEEN 5 AND 7 THEN 2
 WHEN MOD(e.employee_id,100) BETWEEN 8 AND 11 THEN 3
 WHEN MOD(e.employee_id,100) BETWEEN 12 AND 13 THEN 4
 WHEN MOD(e.employee_id,100) BETWEEN 14 AND 16 THEN 5
 WHEN MOD(e.employee_id,100) BETWEEN 17 AND 21 THEN 6
 WHEN MOD(e.employee_id,100)=22 THEN 7
 WHEN MOD(e.employee_id,100) BETWEEN 23 AND 24 THEN 8
 WHEN MOD(e.employee_id,100) BETWEEN 25 AND 26 THEN 9
 WHEN MOD(e.employee_id,100) BETWEEN 27 AND 31 THEN 10
 WHEN MOD(e.employee_id,100) BETWEEN 32 AND 34 THEN 11
 WHEN MOD(e.employee_id,100) BETWEEN 35 AND 37 THEN 12 END,
 e.employee_id,j.job_title,e.hire_date
FROM employees e JOIN jobs j ON j.job_id=e.job_id
WHERE e.status='ACTIVE' AND MOD(e.employee_id,100) BETWEEN 0 AND 37;

-- Tài khoản hệ thống và tài khoản riêng cho từng nhân viên.
-- ADMIN: admin_sys / 123456; HR: hr_manager / 123456; NV0001..NV2500 / 123456.
-- Mỗi tài khoản vẫn lưu password dưới dạng PBKDF2, không lưu plaintext.

-- Tài khoản nhân viên đã nghỉ việc bị khóa; ADMIN/HR vẫn hoạt động.
UPDATE users u JOIN employees e ON e.employee_id=u.employee_id SET u.is_active=IF(e.status='ACTIVE',TRUE,FALSE) WHERE u.user_id > 0;

-- Một số khoản phạt mẫu: nghỉ quá nhiều / vi phạm quy định, sẽ được cộng vào Khấu trừ khi lập phiếu.
SELECT employee_id,'DISCIPLINE',300000,'Nghỉ quá số ngày quy định',DATE_ADD(hire_date,INTERVAL 9 MONTH)
FROM employees WHERE MOD(employee_id,37)=0 AND DATE_ADD(hire_date,INTERVAL 9 MONTH)<=COALESCE(resignation_date,'2026-12-31');

-- Tạo phiếu lương DRAFT cho tháng 1-12 của từng nhân viên còn làm việc trong kỳ; dữ liệu trải đều theo 5 năm.
SELECT e.employee_id,
       MONTH(DATE_ADD(e.hire_date,INTERVAL x.n MONTH)),
       YEAR(DATE_ADD(e.hire_date,INTERVAL x.n MONTH)),
       e.base_salary,
       ROUND(IF(MOD(e.employee_id+MONTH(DATE_ADD(e.hire_date,INTERVAL x.n MONTH)),3)=0,
           (e.base_salary/26/8)*(4+MOD(e.employee_id,10))*1.5,0),0),
       IF(MOD(e.employee_id+MONTH(DATE_ADD(e.hire_date,INTERVAL x.n MONTH)),5)=0,
           1000000+MOD(e.employee_id,5)*500000,0),
       ROUND(e.base_salary*0.08 + COALESCE((SELECT SUM(r.amount) FROM rewards_disciplines r WHERE r.employee_id=e.employee_id AND r.type='DISCIPLINE' AND MONTH(r.record_date)=MONTH(DATE_ADD(e.hire_date,INTERVAL x.n MONTH)) AND YEAR(r.record_date)=YEAR(DATE_ADD(e.hire_date,INTERVAL x.n MONTH))),0),0),
       ROUND(e.base_salary
           +IF(MOD(e.employee_id+MONTH(DATE_ADD(e.hire_date,INTERVAL x.n MONTH)),3)=0,
               (e.base_salary/26/8)*(4+MOD(e.employee_id,10))*1.5,0)
           +IF(MOD(e.employee_id+MONTH(DATE_ADD(e.hire_date,INTERVAL x.n MONTH)),5)=0,
               1000000+MOD(e.employee_id,5)*500000,0)
           -e.base_salary*0.08-COALESCE((SELECT SUM(r.amount) FROM rewards_disciplines r WHERE r.employee_id=e.employee_id AND r.type='DISCIPLINE' AND MONTH(r.record_date)=MONTH(DATE_ADD(e.hire_date,INTERVAL x.n MONTH)) AND YEAR(r.record_date)=YEAR(DATE_ADD(e.hire_date,INTERVAL x.n MONTH))),0),0),
       CASE WHEN DATE_ADD(e.hire_date,INTERVAL x.n MONTH) < '2026-07-01' THEN 'SENT' ELSE 'DRAFT' END
FROM employees e
JOIN (
 SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9
 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15 UNION ALL SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19
 UNION ALL SELECT 20 UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL SELECT 24 UNION ALL SELECT 25 UNION ALL SELECT 26 UNION ALL SELECT 27 UNION ALL SELECT 28 UNION ALL SELECT 29
 UNION ALL SELECT 30 UNION ALL SELECT 31 UNION ALL SELECT 32 UNION ALL SELECT 33 UNION ALL SELECT 34 UNION ALL SELECT 35 UNION ALL SELECT 36 UNION ALL SELECT 37 UNION ALL SELECT 38 UNION ALL SELECT 39
 UNION ALL SELECT 40 UNION ALL SELECT 41 UNION ALL SELECT 42 UNION ALL SELECT 43 UNION ALL SELECT 44 UNION ALL SELECT 45 UNION ALL SELECT 46 UNION ALL SELECT 47 UNION ALL SELECT 48 UNION ALL SELECT 49
 UNION ALL SELECT 50 UNION ALL SELECT 51 UNION ALL SELECT 52 UNION ALL SELECT 53 UNION ALL SELECT 54 UNION ALL SELECT 55 UNION ALL SELECT 56 UNION ALL SELECT 57 UNION ALL SELECT 58 UNION ALL SELECT 59
) x
WHERE DATE_ADD(e.hire_date,INTERVAL x.n MONTH)<=COALESCE(e.resignation_date,'2026-12-31')
  AND YEAR(DATE_ADD(e.hire_date,INTERVAL x.n MONTH)) BETWEEN 2022 AND 2026;

-- Các phiếu SENT của dữ liệu mẫu được xem như đã gửi/đã trả, dùng cho Dashboard.

-- Cập nhật phiếu lương mẫu theo công thức 2026: BH bắt buộc 10,5%, giảm trừ gia cảnh và PIT lũy tiến.
UPDATE payrolls p JOIN employees e ON e.employee_id=p.employee_id
SET p.deduction=COALESCE((SELECT SUM(r.amount) FROM rewards_disciplines r WHERE r.employee_id=e.employee_id AND r.type='DISCIPLINE' AND MONTH(r.record_date)=p.pay_month AND YEAR(r.record_date)=p.pay_year),0),
    p.net_salary=GREATEST(0,
      (p.base_salary+p.overtime_pay+p.bonus) - (p.base_salary*0.105) -
      CASE
        WHEN GREATEST(0,(p.base_salary+p.overtime_pay+p.bonus)-(p.base_salary*0.105)-15500000-COALESCE(e.dependent_count,0)*6200000)<=10000000 THEN GREATEST(0,(p.base_salary+p.overtime_pay+p.bonus)-(p.base_salary*0.105)-15500000-COALESCE(e.dependent_count,0)*6200000)*0.05
        WHEN GREATEST(0,(p.base_salary+p.overtime_pay+p.bonus)-(p.base_salary*0.105)-15500000-COALESCE(e.dependent_count,0)*6200000)<=30000000 THEN 500000+(GREATEST(0,(p.base_salary+p.overtime_pay+p.bonus)-(p.base_salary*0.105)-15500000-COALESCE(e.dependent_count,0)*6200000)-10000000)*0.10
        WHEN GREATEST(0,(p.base_salary+p.overtime_pay+p.bonus)-(p.base_salary*0.105)-15500000-COALESCE(e.dependent_count,0)*6200000)<=60000000 THEN 2500000+(GREATEST(0,(p.base_salary+p.overtime_pay+p.bonus)-(p.base_salary*0.105)-15500000-COALESCE(e.dependent_count,0)*6200000)-30000000)*0.20
        WHEN GREATEST(0,(p.base_salary+p.overtime_pay+p.bonus)-(p.base_salary*0.105)-15500000-COALESCE(e.dependent_count,0)*6200000)<=100000000 THEN 8500000+(GREATEST(0,(p.base_salary+p.overtime_pay+p.bonus)-(p.base_salary*0.105)-15500000-COALESCE(e.dependent_count,0)*6200000)-60000000)*0.30
        ELSE 20500000+(GREATEST(0,(p.base_salary+p.overtime_pay+p.bonus)-(p.base_salary*0.105)-15500000-COALESCE(e.dependent_count,0)*6200000)-100000000)*0.35
      END - p.deduction)
WHERE p.payroll_id > 0;

UPDATE payrolls
SET sent_at = created_at
WHERE payroll_id > 0 AND status='SENT' AND sent_at IS NULL;

CREATE VIEW v_project_staffing AS SELECT p.project_id,p.project_name,p.required_headcount,COUNT(pa.employee_id) current_headcount,GREATEST(0,p.required_headcount-COUNT(pa.employee_id)) missing_headcount FROM projects p LEFT JOIN project_allocations pa ON pa.project_id=p.project_id GROUP BY p.project_id,p.project_name,p.required_headcount;
CREATE VIEW v_department_staffing AS SELECT d.department_name,j.job_title,j.target_headcount,COUNT(CASE WHEN e.status='ACTIVE' THEN 1 END) current_headcount,GREATEST(0,j.target_headcount-COUNT(CASE WHEN e.status='ACTIVE' THEN 1 END)) missing_headcount FROM jobs j JOIN departments d ON d.department_id=j.department_id LEFT JOIN employees e ON e.job_id=j.job_id GROUP BY j.job_id,d.department_name,j.job_title,j.target_headcount;
CREATE VIEW v_employee_timeline AS SELECT e.employee_id,CONCAT('NV',LPAD(e.employee_id,4,'0')) employee_code,e.full_name,e.email,e.hire_date,e.resignation_date,e.status,h.event_type,h.event_date,h.description FROM employees e LEFT JOIN employment_events h ON h.employee_id=e.employee_id;

DROP VIEW IF EXISTS v_employee_projects;
CREATE VIEW v_employee_projects AS SELECT e.employee_id,CONCAT('NV',LPAD(e.employee_id,4,'0')) employee_code,e.full_name,j.job_title,d.department_name,p.project_name,pa.role_in_project,p.status project_status FROM project_allocations pa JOIN employees e ON e.employee_id=pa.employee_id JOIN jobs j ON j.job_id=e.job_id JOIN departments d ON d.department_id=e.department_id JOIN projects p ON p.project_id=pa.project_id;
